<script lang="ts">
  import { onMount, untrack } from 'svelte';
  import Button from '$lib/components/ui/button/button.svelte';
  import { tr } from '../preferences.svelte';
  import { post,message,type Request } from './types';
  let {request,active=true}:{request:Request;active?:boolean}=$props();
  let data=$state<any>(null),busy=$state(false),failure=$state(''),notice=$state(''),hosts=$state(''),deviceName=$state('');
  let exported=$state<any>(null),confirmation=$state<any>(null),timer:ReturnType<typeof setTimeout>;
  let proofPort=$state(''),alive=true,revision=0;
  const date=(value:string)=>Number.isFinite(Date.parse(value))?new Date(value).toLocaleString():tr('Non disponible','Unavailable');
  const validPort=$derived(!proofPort||/^\d+$/.test(proofPort)&&Number(proofPort)>=1&&Number(proofPort)<=65535);
  const current=(stamp:number)=>alive&&active&&stamp===revision;
  function clearExport(){exported=null;clearTimeout(timer);}
  $effect(()=>{if(!active)untrack(()=>{revision++;clearExport();confirmation=null;});else untrack(()=>void load());});
  async function load(){const stamp=revision;try{const result=await request('/api/security/status');if(!current(stamp))return;data=result;if(!hosts)hosts=(data.server?.hosts||data.web?.suggestedHosts||[]).join(', ');if(!proofPort&&data.web?.proofPort)proofPort=String(data.web.proofPort);}catch(error){if(current(stamp))failure=message(error);}}
  function prepare(mode:string){if(validPort)confirmation={action:'prepare',mode,hosts:hosts.split(/[,\s]+/).filter(Boolean),...(proofPort?{candidatePort:Number(proofPort)}:{})};}
  async function action(input:any){if(busy||!data?.web?.csrfToken)return;const stamp=revision;busy=true;failure='';notice='';confirmation=null;try{
    const result=await post(request,'/api/security/actions',input,{'X-Bionic-CSRF':data.web.csrfToken});
    if(!current(stamp))return;
    if(input.action==='issue-device'){clearExport();exported=result;timer=setTimeout(()=>{clearExport();notice=tr('Le téléchargement temporaire a expiré. Le certificat reste dans la liste des appareils.','The temporary download expired. The certificate remains in the device list.');},Math.max(1,Date.parse(result.expiresAt)-Date.now()));deviceName='';await load();if(current(stamp))notice=tr('Certificat créé. Télécharge-le et teste son import avant de retirer un ancien certificat.','Certificate created. Download it and test its import before removing an old certificate.');}
    else {data=result.status||result;notice=tr('État de sécurité actualisé.','Security state updated.');}
  }catch(error){if(!current(stamp))return;failure=message(error);await load();if(current(stamp))notice=tr('État serveur relu. Aucune action n’a été renvoyée automatiquement.','Server state refreshed. No action was automatically submitted again.');}finally{busy=false;}}
  async function download(){if(!exported||busy||exported.downloaded)return;const stamp=revision,item=exported;exported={...item,downloaded:true};busy=true;failure='';try{const response=await fetch('/api/security/device-download',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Bionic-CSRF':data.web.csrfToken},body:JSON.stringify({exportId:item.exportId})});if(!response.ok)throw Error((await response.json()).error);const blob=await response.blob();if(!current(stamp))return;const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='bionic-appareil.p12';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice=tr('Téléchargement demandé au navigateur. Ce lien ne peut servir qu’une fois.','Browser download requested. This link can only be used once.');}catch(error){if(current(stamp)){failure=message(error);notice=tr('Le téléchargement a peut-être été consommé. Vérifie les téléchargements du navigateur avant de renouveler ce certificat. Aucune demande ne sera rejouée.','The download may have been consumed. Check browser downloads before renewing this certificate. No request will be replayed.');}}finally{busy=false;}}
  onMount(()=>()=>{alive=false;revision++;clearExport();});
</script>

<h2>{tr('Connexion sécurisée','Secure connection')}</h2><p class="settings-description">{tr('Consulte et prépare HTTPS ou les certificats d’appareils. L’activation exige une vérification depuis le navigateur ; le code d’accès reste distinct.','Inspect and prepare HTTPS or device certificates. Activation requires a browser verification; the access code remains separate.')}</p>
<Button variant="outline" onclick={load} disabled={busy}>{tr('Actualiser la sécurité','Refresh security')}</Button>
{#if data}<dl class="settings-dl"><dt>{tr('Mode actif','Active mode')}</dt><dd data-testid="security-mode">{data.mode==='mtls'?tr('HTTPS et certificat appareil','HTTPS and device certificate'):data.mode==='https'?'HTTPS':'HTTP'}</dd><dt>{tr('Adresses certifiées','Certified addresses')}</dt><dd>{data.server?.hosts?.join(', ')||tr('Aucun certificat serveur','No server certificate')}</dd><dt>{tr('Expiration serveur','Server expiry')}</dt><dd>{date(data.server?.expiresAt)}</dd><dt>{tr('Empreinte serveur','Server fingerprint')}</dt><dd>{data.server?.fingerprint||'—'}</dd><dt>{tr('Expiration autorité','Authority expiry')}</dt><dd>{date(data.authority?.expiresAt)}</dd><dt>{tr('Empreinte autorité','Authority fingerprint')}</dt><dd>{data.authority?.fingerprint||'—'}</dd></dl>
{#if data.mode==='http'}<p class="settings-feedback">{tr('Les échanges HTTP ne sont pas chiffrés. La préparation conserve cet accès jusqu’à la confirmation sur la page HTTPS de vérification.','HTTP exchanges are unencrypted. Preparation preserves current access until confirmation on the HTTPS verification page.')}</p>{/if}
{#if data.authority}<a class="inline-link" href="/api/security/authority" download>{tr('Télécharger l’autorité publique','Download public authority certificate')}</a><p class="settings-description">{tr('Importe cette autorité publique sur chaque appareil et compare son empreinte par un canal fiable. Les clés privées de l’autorité et du serveur restent sur le PC.','Import this public authority on each device and compare its fingerprint through a trusted channel. The authority and server private keys remain on the PC.')}</p>{/if}
{#if data.web?.canConfigure}<h3>{tr('Préparer une connexion','Prepare a connection')}</h3>
{#if !data.candidate}<label class="setting-field">{tr('Adresses du PC à inclure','PC addresses to include')}<input bind:value={hosts} placeholder="127.0.0.1, localhost, 192.168.1.100" disabled={busy} /></label>
<p class="settings-description">{tr('Inclure les adresses utilisées sur ce PC et sur le réseau local. Renouvelle le certificat si l’adresse du PC change.','Include addresses used on this PC and the local network. Renew the certificate if the PC address changes.')}</p>
<label class="setting-field">{tr('Port de vérification HTTPS','HTTPS verification port')}<input type="number" min="1" max="65535" value={proofPort} oninput={event=>proofPort=event.currentTarget.value} placeholder={tr('Port prévu par le serveur','Server default port')} disabled={busy} /></label>
<p class="settings-description">{tr('Ce port temporaire doit être libre et accessible depuis l’appareil à vérifier. Si le port prévu est occupé, choisis-en un autre explicitement. L’application ne modifie pas le pare-feu.','This temporary port must be free and reachable from the device being verified. If the default port is occupied, explicitly choose another. The application does not change the firewall.')}</p>
{#if !validPort}<p class="settings-error">{tr('Choisis un port entre 1 et 65535.','Choose a port between 1 and 65535.')}</p>{/if}
<div class="settings-actions"><Button variant="outline" disabled={busy||!validPort||!hosts.trim()} onclick={()=>prepare(data.mode==='mtls'?'mtls':'https')}>{data.mode==='http'?tr('Préparer HTTPS','Prepare HTTPS'):tr('Renouveler le serveur','Renew server certificate')}</Button>{#if data.mode==='https'&&data.devices?.some((device:any)=>!device.revokedAt&&Date.parse(device.expiresAt)>Date.now())}<Button variant="outline" disabled={busy||!validPort||!hosts.trim()} onclick={()=>prepare('mtls')}>{tr('Préparer les certificats obligatoires','Prepare required device certificates')}</Button>{/if}</div>{/if}
{#if data.candidate}<div class="settings-feedback" data-testid="security-candidate"><p>{tr('Préparation en attente','Preparation pending')} · {data.candidate.mode} · {date(data.candidate.expiresAt)}</p><dl class="settings-dl"><dt>{tr('Adresse de preuve','Verification address')}</dt><dd>{data.candidate.url}</dd><dt>{tr('Empreinte candidate','Candidate fingerprint')}</dt><dd>{data.candidate.fingerprint||'—'}</dd><dt>{tr('Adresses','Addresses')}</dt><dd>{data.candidate.hosts?.join(', ')||hosts}</dd></dl>{#if data.web.proofPortProvisioned===false}<p>{tr('L’autorisation réseau de ce port n’est pas confirmée pour cette installation. Vérifie le port sur le PC si la page est inaccessible depuis le réseau local.','Network authorization for this port is not confirmed for this installation. Check the port on the PC if the page cannot be reached from the local network.')} {data.candidate.port||data.web.proofPort}</p>{/if}<p>{tr('Après import de l’autorité publique, ouvre la preuve depuis l’appareil à utiliser. Compare les empreintes et ne confirme que sans avertissement de certificat. La confirmation ferme l’ancien accès et exige une nouvelle connexion avec le code d’accès.','After importing the public authority, open verification from the device you will use. Compare fingerprints and confirm only without a certificate warning. Confirmation closes previous access and requires signing in again with the access code.')}</p>{#if data.web.proofRequest}<form action="/api/security/proof" method="post" target="_blank"><input type="hidden" name="proofId" value={data.web.proofRequest.id} /><input type="hidden" name="csrfToken" value={data.web.csrfToken} /><Button type="submit" variant="outline" disabled={busy}>{tr('Ouvrir la vérification HTTPS','Open HTTPS verification')}</Button></form>{:else}<p>{tr('Cette preuve est liée à la session qui l’a créée. Reviens dans ce navigateur, ou annule puis prépare à nouveau depuis cet appareil.','Verification is bound to its initiating session. Return to that browser, or cancel and prepare again from this device.')}</p>{/if}<Button variant="ghost" disabled={busy} onclick={()=>action({action:'cancel-preparation'})}>{tr('Annuler la préparation','Cancel preparation')}</Button></div>{/if}
{:else}<p class="settings-feedback">{tr('Le transport de sécurité n’est pas attaché à ce démarrage. Relance cette instance avec son lanceur de transport habituel pour préparer HTTPS et mTLS.','The security transport is not attached to this startup. Restart this instance with its normal transport launcher to prepare HTTPS and mTLS.')}</p>{/if}
<h3>{tr('Appareils autorisés','Authorized devices')}</h3>
{#if !data.web?.canIssueDevice}<p class="settings-description">{tr('Les certificats privés d’appareils se créent et se téléchargent uniquement depuis une session HTTPS authentifiée. Active d’abord HTTPS, puis reconnecte-toi.','Private device certificates can only be created and downloaded from an authenticated HTTPS session. Activate HTTPS first, then sign in again.')}</p>{/if}
{#if !data.devices?.length}<p class="settings-description">{tr('Aucun certificat appareil.','No device certificate.')}</p>{/if}<ul class="settings-list">{#each data.devices||[] as device (device.id)}<li data-device-id={device.id}><strong>{device.name}</strong><p>{device.revokedAt?tr('Révoqué','Revoked'):Date.parse(device.expiresAt)<Date.now()?tr('Expiré','Expired'):tr('Autorisé','Authorized')} · {date(device.expiresAt)}</p>{#if device.revokedAt}<p>{tr('Retiré le','Revoked on')} {date(device.revokedAt)}</p>{/if}<details><summary>{tr('Empreinte','Fingerprint')}</summary><code>{device.fingerprint}</code></details>{#if data.web?.canIssueDevice&&!device.revokedAt}<div class="settings-actions"><Button variant="outline" disabled={busy} onclick={()=>confirmation={action:'issue-device',previousId:device.id}}>{tr('Renouveler','Renew')}</Button>{#if data.web.currentDeviceId!==device.id}<Button variant="ghost" disabled={busy} onclick={()=>confirmation={action:'revoke-device',id:device.id,confirmName:device.name}}>{tr('Révoquer cet appareil','Revoke device')}</Button>{:else}<span>{tr('Connexion actuelle','Current connection')}</span>{/if}</div>{/if}</li>{/each}</ul>
{#if data.web?.canIssueDevice}<form onsubmit={event=>{event.preventDefault();confirmation={action:'issue-device',name:deviceName.trim()};}}><label class="setting-field">{tr('Nom du nouvel appareil','New device name')}<input bind:value={deviceName} maxlength="80" required disabled={busy} /></label><Button type="submit" disabled={busy||!deviceName.trim()}>{tr('Créer un certificat appareil','Create device certificate')}</Button></form>{/if}
{#if exported}<div class="confirm-action" data-testid="security-export"><h4>{tr('Certificat disponible temporairement','Certificate available temporarily')}</h4><p class="settings-description">{tr('Le mot de passe sert uniquement à importer ce fichier sur ton appareil. Il est effacé de ce panneau à sa fermeture ou à l’expiration et n’est pas conservé dans les préférences du navigateur.','This password is only used to import the file on your device. It is cleared from this panel on closure or expiry and is not saved in browser preferences.')}</p>{#if exported.previousId}<p>{tr('L’ancien certificat reste actif. Teste le nouveau sur l’appareil avant de révoquer l’ancien dans la liste.','The old certificate remains active. Test the new one on the device before revoking the old one in the list.')}</p>{/if}<label class="setting-field">{tr('Mot de passe du certificat','Certificate password')}<input readonly value={exported.passphrase} type="text" autocomplete="off" /></label><p>{tr('Expiration du téléchargement','Download expires')} : {date(exported.expiresAt)}</p><div class="settings-actions"><Button onclick={download} disabled={busy||exported.downloaded}>{tr('Télécharger le certificat .p12','Download .p12 certificate')}</Button><Button variant="ghost" onclick={clearExport}>{tr('Masquer ces informations','Hide this information')}</Button></div></div>{/if}
<p class="settings-description">{tr('Une expiration ou une erreur ne réactive pas HTTP. Pour une récupération locale, utilise Certificats.cmd sur le PC. Les changements de niveau et téléchargements ne sont jamais rejoués automatiquement.','Expiry or failure never reactivates HTTP. Use Certificats.cmd on the PC for local recovery. Security changes and downloads are never automatically replayed.')}</p>
{/if}
{#if confirmation}<div class="confirm-action" role="group" aria-label={tr('Confirmer la modification de sécurité','Confirm security change')}><h3>{tr('Confirmer la modification','Confirm change')}</h3><p>{confirmation.action==='revoke-device'?tr('Retirer l’accès de cet appareil : ','Remove access for this device: ')+confirmation.confirmName:confirmation.action==='issue-device'?tr('Créer un certificat privé à importer sur l’appareil choisi.','Create a private certificate to import on the chosen device.'):tr('Préparer le nouveau certificat puis vérifier son accès avant activation.','Prepare the new certificate, then verify access before activation.')}</p><div class="settings-actions"><Button onclick={()=>action(confirmation)} disabled={busy}>{tr('Confirmer','Confirm')}</Button><Button variant="ghost" onclick={()=>confirmation=null}>{tr('Annuler','Cancel')}</Button></div></div>{/if}
{#if failure}<p class="settings-error" role="alert">{failure}</p>{/if}{#if notice}<p class="settings-feedback" role="status">{notice}</p>{/if}
